+                    style="width: 40px; height: 40px; font-size: 0.85rem;"
+                    disabled="@(!isClickable)"
+                    @onclick="() => OnStepClicked.InvokeAsync(step)">
+                @if (isCompleted && !isActive)
+                {
+                    <span>✓</span>
+                }
+                else
+                {
+                    <span>@step</span>
+                }
+            </button>
+            <div class="small mt-1 @(isActive ? "fw-bold" : isCompleted ? "" : "text-muted")">@label</div>
+        </div>
+
+        @if (i < _steps.Length - 1)
+        {
+            <div class="flex-fill d-flex align-items-center" style="margin-top: -20px;">
+                <hr class="w-100 @(CompletedSteps.Contains(step) ? "border-primary" : "border-secondary")"
+                    style="border-width: 2px;" />
+            </div>
+        }
+    }
+</nav>
+
+@code {
+    [Parameter] public int CurrentStep { get; set; }
+    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
+    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
+
+    private static readonly string[] _steps =
+    {
+        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
+    };
+
+    private static string StepBadgeClass(bool isActive, bool isCompleted) =>
+        isActive ? "btn-primary" :
+        isCompleted ? "btn-success" :
+        "btn-outline-secondary";
+}
+

